import{_ as a,o,c as r,ae as e}from"./chunks/framework.DFTT1zkb.js";const b=JSON.parse('{"title":"校园流量卡","description":"","frontmatter":{},"headers":[],"relativePath":"begin/calling_card.md","filePath":"begin/calling_card.md"}'),s={name:"begin/calling_card.md"};function l(n,t,c,i,d,p){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="校园流量卡" tabindex="-1">校园流量卡 <a class="header-anchor" href="#校园流量卡" aria-label="Permalink to &quot;校园流量卡&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>几乎所有情况下的校园卡均指<strong>校园流量卡</strong></p></div><p>只是一种为大学生定制的带有套餐的流量卡，与其他套餐流量卡并无本质区别，与营业厅的普通套餐相比可能便宜一些</p><p><strong>根据个人需求可以自行考虑办理</strong>，如果不需要那就大胆拒绝就可以了</p><p>如果真的有需要，也可以携带身份证和学生证，自行前往教二402网络服务中心，随时办理随时激活。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><ul><li>在开学期间会有大部分主动推销校园流量卡的学长/学姐/工作人员，请勿听信其推销话语，谨慎考虑办理</li><li>过去曾有过校外人员伪装成在校学生卖卡后跑路的诈骗案例，务必<strong>擦亮眼睛谨慎判断对方身份</strong></li><li>碰到<strong>故意夸大校园流量卡的重要性（比如说不办卡就吃不了饭进不了学校等等）、甚至说一些如&quot;校园宽带&quot;等不清不楚的名词混淆概念</strong> 的学长学姐，一律视为骗子，直接拉黑删除</li></ul></div><h2 id="参考价格" tabindex="-1">参考价格 <a class="header-anchor" href="#参考价格" aria-label="Permalink to &quot;参考价格&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>此处价格来自于 2026 年学长办理校园流量卡时的宣传图，套餐内容仅供参考</strong><strong>校园流量卡目前只有一种套餐价格，且只有移动和电信流量卡</strong></p></div><table tabindex="0"><thead><tr><th>月租</th><th style="text-align:center;">39 元/月</th></tr></thead><tbody><tr><td>全国通话</td><td style="text-align:center;">200分钟</td></tr><tr><td>全国流量</td><td style="text-align:center;">200GB</td></tr></tbody></table><h2 id="学长-学姐为什么推销电话卡" tabindex="-1">学长/学姐为什么推销电话卡 <a class="header-anchor" href="#学长-学姐为什么推销电话卡" aria-label="Permalink to &quot;学长/学姐为什么推销电话卡&quot;">​</a></h2><p>认识学弟学妹，顺便赚点零花钱，吃点小回扣</p><p>办一张回扣通常在 100 元左右，对于大学生来说吸引力确实够大的</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>校方对在校学生从事校园卡、二手书的推销的态度尚不明确，但<strong>禁止进入宿舍挨个“上门推销”</strong></p><blockquote><p>大家自觉抵制各类上门推销、兜售等行为，谨防有人冒充学校老师、学生等进行诈骗和推销。<br> 严禁在学生宿舍进行各类推销（手机卡、学习资料及其他各类物品）行为，如发现有上门推销、兜售商品的，请及时报告宿管。</p></blockquote><p>不少人能对卖卡的行为表示一定的理解和接受。</p><p><mark>但是倘若遇到<strong>某些</strong>学长学姐死缠烂打或是因不办卡而恶意骚扰以至于<strong>影响了个人生活</strong>，<strong>请务必立即向辅导员汇报</strong>，由学校介入处理</mark></p></div>',13)])])}const u=a(s,[["render",l]]);export{b as __pageData,u as default};
